import {title,hero,rooms,photos,description,amenities,reviews,chips} from './data.js';
export const icon=(n,cls='')=>`<img class="icon ${cls}" src="assets/svg-${n}.svg" alt="">`;
export const photo=(id,alt,extra='')=>`<img src="assets/${id}.jpeg" alt="${alt}" ${extra}>`;
export const more=action=>`<button class="text-link more"${action?` data-action="${action}"`:''}>Show more ${icon(17)}</button>`;
export function reviewCard(r,i,expanded=false){return `<article class="review"><div class="review-person">${r.avatar?`<img src="assets/${r.avatar}" alt="">`:`<span class="avatar-letter">${r.name[0]}</span>`}<div><b>${r.name}</b><small>${r.tenure}</small></div></div><div class="review-date"><span>★★★★★</span> · ${r.date}</div><p class="${expanded?'':'clamp'}">${r.text.replaceAll('\n','<br>')}</p>${r.text.length>180&&!expanded?`<button class="text-link" data-action="review-toggle" data-index="${i}">Show more</button>`:''}</article>`}
export function renderViews(){
 document.querySelector('#hero-grid').innerHTML=hero.map((id,i)=>`<button data-action="tour" aria-label="${title} image ${i+1}">${photo(id,['Private patio lounge','Lounge with jacuzzi','Private jacuzzi','Bedroom','Apartment exterior'][i])}</button>`).join('');
 document.querySelector('#property-details').innerHTML=`<section class="highlights">${[['Outdoor entertainment','The pool and alfresco dining are great for summer trips.',14],['Designed for staying cool','Beat the heat with the A/C and ceiling fan.',15],['Self check-in','You can check in with the building staff.',16]].map(([h,p,i])=>`<div>${icon(i)}<div><b>${h}</b><p>${p}</p></div></div>`).join('')}</section><section class="description-section"><div class="translation">Some info has been automatically translated. <a class="text-link" href="#">Show original</a></div><p class="description-clamp">${description}</p>${more('description')}</section><section class="sleep-section"><h2>Where you'll sleep</h2><div class="sleep-cards">${[[3,'Bedroom','1 double bed'],[0,'Living room','1 sofa']].map(([r,t,b])=>`<div><div class="sleep-photo">${photo(rooms[r].photos[0],t,'loading="lazy"')}</div><b>${t}</b><p>${b}</p></div>`).join('')}</div></section><section id="amenities"><h2>What this place offers</h2><div class="amenities-grid">${amenities.map(([a,n],i)=>`<div class="${i>7?'unavailable':''}">${icon(n)}<span>${a}</span></div>`).join('')}</div><button class="outline-button" data-action="amenities">Show all 50 amenities</button></section><section class="calendar-section" id="calendar"><h2 id="stay-title">5 nights in Candolim</h2><p id="stay-dates">18 Oct 2026 - 23 Oct 2026</p><div id="calendar-inline"></div></section>`;
 document.querySelector('#wide-sections').innerHTML=`<section id="reviews" class="wide-section"><div class="review-heading"><div class="big-rating"><img src="assets/laurel-left.png" alt=""><strong>4.95</strong><img src="assets/laurel-right.png" alt=""></div><h2>Guest favourite</h2><p>This home is a guest favourite based on ratings, reviews and<br> reliability</p><button class="text-link">How reviews work</button></div><div class="ratings-breakdown"><div class="overall-rating"><b>Overall rating</b>${[5,4,3,2,1].map((v,i)=>`<div><span>${v}</span><i><em style="width:${[95,5,0,0,0][i]}%"></em></i></div>`).join('')}</div>${[['Cleanliness','5.0',33],['Accuracy','5.0',34],['Check-in','5.0',35],['Communication','5.0',36],['Location','4.8',37],['Value','4.8',38]].map(([s,r,i])=>`<div><b>${s}</b><strong>${r}</strong>${icon(i)}</div>`).join('')}</div><div class="review-chips">${chips.map(([c,n])=>`<button><img src="assets/${c.toLowerCase().replaceAll(' ','-')}.png" alt="">${c}<span>${n}</span></button>`).join('')}</div><div class="review-grid">${reviews.map((r,i)=>reviewCard(r,i)).join('')}</div><button class="outline-button">Show all 19 reviews</button></section><section id="location" class="wide-section"><h2>Where you’ll be</h2><p class="location-name">Candolim, Goa, India</p><div class="map" aria-label="Approximate location in Candolim, Goa"><div class="map-art"><div class="coast"></div><div class="park park-one"></div><div class="park park-two"></div><div class="map-grid"></div></div><button class="map-home" aria-label="Property location">${icon(72)}</button><button class="map-search" aria-label="Search">${icon(69)}</button><div class="map-zoom"><button aria-label="Zoom in">${icon(70)}</button><button aria-label="Zoom out">${icon(71)}</button></div></div><p class="exact-location">Exact location will be provided after booking.</p><h3>Neighbourhood highlights</h3><p class="neighbourhood">Located in the heart of Candolim, Amor de Goa offers a peaceful stay with easy access to beaches, cafés, and popular attractions.</p>${more()}</section><section class="wide-section" id="host"><h2>Meet your host</h2><div class="host-layout"><div><div class="host-card"><div class="host-profile"><img src="assets/host.jpeg" alt="Mirashya Homes"><span class="verified">✓</span><h2>Mirashya<br>Homes</h2><p>Host</p></div><div class="host-stats"><div><b>1,463</b><small>Reviews</small></div><div><b>4.68★</b><small>Rating</small></div><div><b>2</b><small>Years hosting</small></div></div></div><p class="host-fact">${icon(75)}Born in the 80s</p><p class="host-fact">${icon(76)}Where I went to school: NICMAR GOA</p></div><div><h3>Co-Hosts</h3><div class="cohosts">${[['Sharath','co1.jpg'],['Aman Dev Pahwa','co2.jpg'],['Maria Karen Priyanka','co3.jpg'],['Simran','rev5.jpeg'],['Pallavi','rev1.jpeg'],['Sanyukta','rev2.jpeg'],['Shruti',null],['Amisha',null]].map(([n,a])=>`<div>${a?`<img src="assets/${a}" alt="">`:`<span class="avatar-letter">${n[0]}</span>`}<span>${n}</span></div>`).join('')}</div><h3>Host details</h3><p class="host-response">Response rate: 100%<br>Responds within an hour</p><button class="soft-button message-host">Message host</button><p class="payment-note">${icon(77)}To help protect your payment, always use Airbnb to send money and communicate with hosts.</p></div></div></section><section class="wide-section"><h2>Things to know</h2><div class="things-grid">${[[78,'Cancellation policy','Free cancellation before 17 October. Cancel before check-in on 18 October for a partial refund.<p>Review this host’s full policy for details.</p>'],[79,'House rules','Check-in after 2:00 pm<p>Checkout before 11:00 am</p><p>3 guests maximum</p>'],[80,'Safety & property','Carbon monoxide alarm not reported<p>Smoke alarm not reported</p><p>Exterior security cameras on property</p>']].map(([i,t,d])=>`<div>${icon(i)}<h3>${t}</h3><div>${d}</div><a class="text-link" href="#">Learn more</a></div>`).join('')}</div></section><section class="wide-section nearby"><div class="nearby-heading"><h2>More stays nearby</h2><div><span id="similar-page">1 / 2</span><button class="round-arrow" data-action="similar-prev" aria-label="Previous stays" disabled>${icon(28)}</button><button class="round-arrow" data-action="similar-next" aria-label="Next stays">${icon(29)}</button></div></div><div class="similar-track">${[['Beautiful Studio with a view to die for','23,600','4.91',1],['NAQAB - 1bhk with private pool','42,218','4.95',2],['Greentique Luxury Flat with plunge pool, Calangute','44,506','4.94',3],['The Tropical Studio | 5 mins to Beach','22,824','4.96',4],['Luxury Casa Bella 1BHK with plunge pool, Calangute','39,942','4.95',5],['Kanso by Earthen Window | Jacuzzi | Terrace | Pool','45,648','5.0',6],['Luxury Apt | Private Pool | 6 Mins from Beach','48,786','4.93',2],['Serendipity Cottage - Calm Stay in Calangute-Baga.','22,824','4.92',4]].map(([t,p,r,i])=>`<article><img src="assets/s${i}.jpeg" alt="${t}" loading="lazy"><b>${t}</b><p>₹${p} &nbsp;★${r}</p></article>`).join('')}</div></section>`;
 document.querySelector('#tour-nav').innerHTML=rooms.map((r,i)=>`<button data-action="jump-room" data-room="${i}">${photo(r.photos[0],r.name)}<span>${r.name}</span></button>`).join('');
 let count=0;document.querySelector('#tour-rooms').innerHTML=rooms.map((r,i)=>`<section class="tour-room" id="room-${i}"><div class="room-description"><h2>${r.name}</h2>${r.features?`<p>${r.features}</p>`:''}</div><div class="room-photos">${r.photos.map((p,j)=>`<button data-action="photo" data-index="${count++}" aria-label="${title} image ${photos.findIndex(x=>x.id===p)+1}">${photo(p,r.name,'loading="lazy"')}</button>`).join('')}</div></section>`).join('');
 const nav=document.createElement('nav');nav.className='section-nav';nav.setAttribute('aria-label','Listing sections');nav.innerHTML=`<div><div class="section-links">${['Photos','Amenities','Reviews','Location'].map(s=>`<a href="#${s.toLowerCase()}">${s}</a>`).join('')}</div><div class="nav-reserve"><div><b data-nav-price>₹28,499</b> for <span data-nights>5</span> nights<small>★ 4.95 · 19 reviews</small></div><button class="reserve" data-action="reserve">Reserve</button></div></div>`;document.querySelector('#listing').prepend(nav);
}
